    d=dict(id=id,outName=out,grade="GRADE 9-10",course="AP PRECALCULUS",topicNo="UNIT 1",lessonNo=topic,topicTitle="Polynomial and Rational Functions",eq=None,mps=None,exam=EXAM,noExam=True)
