c11=cfg("AP1-11","AP Precalculus Topic 1.11 Equivalent Representations of Polynomial and Rational Expressions presentation",["Equivalent","Representations"],"Topic 1.11",
 titleMath="x^{2}-1=(x-1)(x+1)",codes="LO 1.11.A · LO 1.11.B · LO 1.11.C",
 objectives=["Rewrite polynomial and rational expressions in equivalent forms.","Determine the quotient of two polynomial functions using long division.","Rewrite the repeated product of binomials using the binomial theorem."],
 vocab=["factored form","standard form","equivalent forms","polynomial long division","quotient","remainder","slant asymptote","binomial theorem","Pascal's Triangle"],
 standards=[{"code":"LO 1.11.A","text":"Rewrite polynomial and rational expressions in equivalent forms."},{"code":"LO 1.11.B","text":"Determine the quotient of two polynomial functions using long division."},{"code":"LO 1.11.C","text":"Rewrite the repeated product of binomials using the binomial theorem."}],
 diagnose=dict(items=["\\text{Factor }x^{2}-x-12","\\text{Simplify }\\dfrac{x^{2}-9}{x+3}","\\text{Expand }(x-2)^{2}"],
  doneWhen="All three answers are written without a calculator, and you can say how you checked each one by multiplying back.",
  notes="Speaker notes (Diagnose, 6 min, no calculator).\nSolutions: Q1 x^2 - x - 12 = (x - 4)(x + 3), because -4 and 3 multiply to -12 and add to -1. Q2 (x - 3)(x + 3)/(x + 3) = x - 3 for x not equal to -3. Q3 (x - 2)^2 = x^2 - 4x + 4.\nVerbal misconceptions: 'factor pairs only need the right product' (check the sum); 'cancel the x^2 and the 9'; '(x - 2)^2 = x^2 - 4' (the middle term is missing).\nAdaptive routing: if more than 30% miss Q1 or Q2, route to slide 5 (factored form). If more than 30% miss Q3, route to slide 7 (binomial theorem)."),
 blocks=[
 dict(title="Factored form and standard form",rules=["\\text{Factored form: zeros, intercepts, asymptotes, holes}","\\text{Standard form: end behavior}"],
  examples=[dict(q="f(x)=x^{3}-4x^{2}-5x",steps=["f(x)=x(x-5)(x+1)","\\text{zeros: }x=-1,\\ 0,\\ 5","\\lim_{x\\to\\infty}f(x)=\\infty"]),
            dict(q="r(x)=\\dfrac{x^{2}-x-6}{x^{2}-9}",steps=["r(x)=\\dfrac{(x-3)(x+2)}{(x-3)(x+3)}","\\text{hole }\\left(3,\\dfrac{5}{6}\\right),\\ \\text{VA }x=-3","\\text{zero }x=-2,\\ \\text{HA }y=1"])],fig=None,
  notes="Speaker notes (Targeted Instruction, block 1 of 3, LO 1.11.A). EK 1.11.A.1: 'Because the factored form of a polynomial or rational function readily provides information about real zeros, it can reveal information about x-intercepts, asymptotes, holes, domain, and range.' EK 1.11.A.2: 'The standard form of a polynomial or rational function can reveal information about end behaviors of the function.' EK 1.11.A.3: 'The information extracted from different analytic representations of the same polynomial or rational function can be used to answer questions in context.'\nWorked solutions: Example A: x^3 - 4x^2 - 5x = x(x^2 - 4x - 5) = x(x - 5)(x + 1); zeros -1, 0, 5. The standard form has leading term x^3, so f tends to infinity as x tends to infinity. Example B: x^2 - x - 6 = (x - 3)(x + 2) and x^2 - 9 = (x - 3)(x + 3). The common factor x - 3 gives a hole at x = 3; the reduced function (x + 2)/(x + 3) has value 5/6 there, so the hole is (3, 5/6). The factor x + 3 stays in the denominator: vertical asymptote x = -3. The zero is x = -2. Equal degrees with ratio 1/1 give the horizontal asymptote y = 1.\nVerbal misconceptions: 'a common factor that cancels leaves no trace' (it leaves a hole); 'a hole and a vertical asymptote are the same thing'.\nAdaptive routing: if more than 30% miss Gate Q1, return to this slide and redo Example A aloud."),
 dict(title="Polynomial long division",rules=["f(x)=g(x)\\,q(x)+r(x)","\\deg r<\\deg g"],
  examples=[dict(q="\\dfrac{2x^{3}-3x^{2}+x+5}{x-2}",steps=["=(x-2)(2x^{2}+x+3)+11","q(x)=2x^{2}+x+3,\\ r(x)=11","2x^{2}+x+3+\\dfrac{11}{x-2}"]),
            dict(q="r(x)=\\dfrac{x^{2}+3x-1}{x-1}",steps=["r(x)=x+4+\\dfrac{3}{x-1}","\\text{slant asymptote }y=x+4","\\text{vertical asymptote }x=1"])],
  fig=dict(file="figs/AP1-11_slant.png",w=1230,h=930),
  notes="Speaker notes (Targeted Instruction, block 2 of 3, LO 1.11.B). EK 1.11.B.2: 'The result of polynomial long division is helpful in finding equations of slant asymptotes for graphs of rational functions.' EK 1.11.B.1 describes long division as an algebraic process similar to numerical long division with a quotient and a remainder; the fetched wording was partly garbled (check against the CED PDF).\nWorked solutions: Example A: divide by x - 2 (synthetic division with 2): coefficients 2, -3, 1, 5 become 2, 1, 3, 11. So the quotient is 2x^2 + x + 3 and the remainder is 11; check: (x - 2)(2x^2 + x + 3) = 2x^3 - 3x^2 + x - 6 ... plus 11 gives 2x^3 - 3x^2 + x + 5. Example B: divide by x - 1 with 1: coefficients 1, 3, -1 become 1, 4, 3. So r(x) = x + 4 + 3/(x - 1). As x grows large the fraction tends to 0, so the graph approaches the line y = x + 4. The denominator is zero at x = 1: vertical asymptote.\nVerbal misconceptions: 'the remainder goes in the quotient'; 'the degree of the remainder can equal the degree of the divisor'; 'a slant asymptote is the same as a horizontal asymptote'.\nAdaptive routing: if more than 30% miss Gate Q2, return to this slide and redo Example A with the remainder written as a fraction."),
 dict(title="The binomial theorem",rules=["\\text{Pascal row }n:\\ \\text{coefficients of }(a+b)^{n}"],
  examples=[dict(q="(x+2)^{4}",steps=["\\text{Row }4:\\ 1,\\ 4,\\ 6,\\ 4,\\ 1","\\text{terms: }1,\\ 4\\cdot2,\\ 6\\cdot4,\\ 4\\cdot8,\\ 16","x^{4}+8x^{3}+24x^{2}+32x+16"]),
            dict(q="(x-3)^{3}",steps=["\\text{Row }3:\\ 1,\\ 3,\\ 3,\\ 1","x^{3}+3x^{2}(-3)+3x(9)-27","x^{3}-9x^{2}+27x-27"]),
            dict(q="(2x+1)^{3}",steps=["\\text{Row }3:\\ 1,\\ 3,\\ 3,\\ 1","8x^{3}+3(4x^{2})+3(2x)+1","8x^{3}+12x^{2}+6x+1"])],fig=None,
  notes="Speaker notes (Targeted Instruction, block 3 of 3, LO 1.11.C). EK 1.11.C.1 (partly garbled in the fetched text; check against the CED PDF): the binomial theorem uses one row of Pascal's Triangle to expand (a + b)^n more easily, including polynomial functions of the form p(x) = (x + c)^n.\nWorked solutions: Example A: row 4 is 1, 4, 6, 4, 1. Powers of 2 are 1, 2, 4, 8, 16, giving x^4 + 8x^3 + 24x^2 + 32x + 16. Example B: row 3 is 1, 3, 3, 1 with c = -3: powers of -3 are 1, -3, 9, -27, so x^3 - 9x^2 + 27x - 27. Example C: a = 2x, b = 1: 8x^3 + 3(4x^2) + 3(2x) + 1 = 8x^3 + 12x^2 + 6x + 1.\nVerbal misconceptions: '(x + 2)^4 = x^4 + 16' (the middle terms are missing); 'the coefficient is only the Pascal number' (multiply by the power of c); 'with a negative c every sign is positive'; 'in (2x + 1)^3 the 2 is not cubed'.\nAdaptive routing: if more than 30% miss Gate Q3, return to this slide; build Pascal rows 1 to 5 on the board first."),
 ],
 practice=dict(practice=dict(items=["\\dfrac{x^{3}+2x^{2}-5x+1}{x-1}"],done="Done when: you write the result as quotient plus remainder over the divisor and name the quotient and the remainder."),
  apply=dict(items=["\\begin{array}{c}\\text{A cube has edge }(x+2)\\text{ cm.}\\\\ \\text{Write its volume in standard form.}\\end{array}"],done="Done when: the expansion uses a row of Pascal's Triangle and you check it with edge 3 cm (volume 27 cubic centimetres)."),
  investigate=dict(items=["\\begin{array}{c}\\text{Why does }\\dfrac{x^{2}-9}{x-3}\\text{ have a hole,}\\\\ \\text{not an asymptote, at }x=3?\\end{array}"],done="Done when: your explanation names the common factor and gives the coordinates of the hole."),
  notes="Speaker notes (Practice, 12 min; tierless: students choose the starting column and may move across).\nAnswers: Practice: synthetic division with 1: coefficients 1, 2, -5, 1 become 1, 3, -2, -1, so the quotient is x^2 + 3x - 2 and the remainder is -1: x^2 + 3x - 2 - 1/(x - 1). Apply: (x + 2)^3 = x^3 + 6x^2 + 12x + 8; at x = 1 this is 27 = 3^3. Investigate: (x^2 - 9)/(x - 3) = (x + 3)(x - 3)/(x - 3); the factor x - 3 cancels, so the graph is the line y = x + 3 with a hole at (3, 6).\nVerbal misconceptions: 'if the denominator is zero there is always an asymptote'.\nAdaptive routing: finished students move to Apply then Investigate; stuck students return to slide 6."),
 production=dict(title="average cost at a workshop",context="A workshop makes custom phone cases. The model below gives the average cost in dollars per case when a given number of hundreds of cases is made. The numbers are model values for practice, not real costs.",
  given=["A(x)=\\dfrac{x^{2}+8x+30}{x+2}","x\\ge 1"],
  tasks=["Use long division to write the average cost as quotient plus remainder over the divisor.","State the slant asymptote and say what it tells the workshop about large orders.","Check your rewritten form by finding the average cost for 800 cases both ways."],
  doneWhen=["The quotient and remainder are both named.","The slant asymptote is written as an equation.","The meaning is given in dollars per case.","Both values for 800 cases are equal and shown."],
  hint="Hint: divide by x + 2, so use -2 in synthetic division.",
  notes="Speaker notes (Production, 12 min).\nSolutions: Synthetic division with -2: coefficients 1, 8, 30 become 1, 6, 18. So A(x) = x + 6 + 18/(x + 2): quotient x + 6, remainder 18. Task 2: the slant asymptote is y = x + 6; for large orders the average cost per case is close to x + 6 dollars, so it keeps growing with x in this model. Task 3: original form (64 + 64 + 30)/10 = 15.8; rewritten form 8 + 6 + 18/10 = 15.8; both 15.80 dollars.\nVerbal misconceptions: using +2 in synthetic division; writing the remainder as a number added to the quotient.\nAdaptive routing: if students cannot start, send them to slide 6 Example A and the hint."),
 gate=dict(items=["\\text{Zeros of }f(x)=x^{3}-9x","\\dfrac{x^{2}+5x+7}{x+2}=\\ ?","(x+2)^{3}=\\ ?"],
  notes="Speaker notes (Mastery Gate, 6 min, no calculator).\nAnswers: Q1 x^3 - 9x = x(x - 3)(x + 3), zeros -3, 0, 3. Q2 synthetic division with -2: 1, 5, 7 become 1, 3, 1, so x + 3 + 1/(x + 2). Q3 x^3 + 6x^2 + 12x + 8.\nVerbal misconceptions: Q1 'divide by x and lose the zero at 0'; Q2 'remainder 1 written as +1 in the quotient'; Q3 'x^3 + 8'.\nAdaptive routing: Q1 missed, route to slide 5 Example A; Q2 missed, route to slide 6 Example A; Q3 missed, route to slide 7."),
 smart=dict(create=["Write a rational function in factored form with a hole where x is 2 and a vertical asymptote where x is negative 1.","Expand it to standard form on the back.","Swap with a partner: they find the hole, the asymptote and one zero."],
  createDone="Done when: your partner confirms the hole, the asymptote and the zero from the factored form.",
  exitIntro="Exit ticket: write your answer on a sticky note and place it on the door.",exit=["(x-1)^{4}=\\ ?"],
  next="Next lesson: Topic 1.12 Transformations of Functions.",
  notes="Speaker notes (Smart Production, 6 min).\nCreate example: (x - 2)(x + 3)/((x - 2)(x + 1)): hole where x = 2 (y = 5/3), asymptote x = -1, zero x = -3. Exit answer: row 4 with c = -1: x^4 - 4x^3 + 6x^2 - 4x + 1.\nVerbal misconceptions: students keep all signs positive; ask: what happens to the sign of each term when c is negative?"),
 recap="Factored form shows zeros and holes, standard form shows end behavior, long division reveals the slant asymptote, and Pascal's Triangle expands repeated binomials.")

