 blocks=[
 dict(title="Choosing a function type from the data",rules=["\\text{constant }\\Delta y\\Rightarrow\\text{linear}","\\text{constant }\\Delta^{2}y\\Rightarrow\\text{quadratic}"],
  examples=[dict(q="\\begin{array}{c}x:\\ 0,1,2,3,4,5\\\\ y:\\ 3,7,11,15,19,23\\end{array}",steps=["\\Delta y=4,4,4,4,4","\\text{linear: }y=4x+3"]),
            dict(q="\\begin{array}{c}x:\\ 0,1,2,3,4\\\\ y:\\ 2,5,12,23,38\\end{array}",steps=["\\Delta y=3,7,11,15","\\Delta^{2}y=4,4,4\\Rightarrow\\text{quadratic}","y=2x^{2}+x+2"])],
  fig=dict(file="figs/AP1-13_models.png",w=1230,h=930),
  notes="Speaker notes (Targeted Instruction, block 1 of 3, LO 1.13.A). EK 1.13.A.1: 'Linear functions model data sets or aspects of contextual scenarios that demonstrate roughly constant rates of change.' EK 1.13.A.2: 'Quadratic functions model data sets or aspects of contextual scenarios that demonstrate roughly linear rates of change, or data sets that are roughly symmetric with a unique maximum or minimum value.'\nWorked solutions: Example A: the inputs step by 1 and every output rises by 4, so the rate is constant and the model is linear; slope 4, y-intercept 3: y = 4x + 3. Example B: first differences 3, 7, 11, 15 are not constant, second differences 4, 4, 4 are, so the model is quadratic with 2a = 4, a = 2. Using (0, 2): c = 2; using (1, 5): 2 + b + 2 = 5, b = 1. So y = 2x^2 + x + 2; check x = 3: 18 + 3 + 2 = 23.\nVerbal misconceptions: 'differences that change mean the data is not a function'; 'the second difference equals a' (it equals 2a for unit steps).\nAdaptive routing: if more than 30% miss Gate Q1, return to this slide and tabulate the differences for Example B."),
 dict(title="Degree n and geometric contexts",rules=["\\text{constant }\\Delta^{n}y\\Rightarrow\\text{degree }n","n+1\\text{ points, distinct inputs}\\Rightarrow\\text{degree}\\le n"],
  examples=[dict(q="\\begin{array}{c}x:\\ 0,1,2,3,4\\\\ y:\\ 1,3,11,31,69\\end{array}",steps=["\\Delta y=2,8,20,38","\\Delta^{2}y=6,12,18;\\ \\Delta^{3}y=6,6","\\text{constant }\\Delta^{3}y\\Rightarrow\\text{cubic}"]),
            dict(q="\\text{Volume of an open box, edge }x",steps=["\\text{three dimensions}\\Rightarrow\\text{cubic}","V(x)=x(20-2x)^{2}","\\text{a degree 3 polynomial}"]),
            dict(q="\\text{Six points, distinct inputs}",steps=["n+1=6\\Rightarrow n=5","\\text{a polynomial of degree}\\le5","\\text{fits all six points}"])],fig=None,
  notes="Speaker notes (Targeted Instruction, block 2 of 3, LO 1.13.A). EK 1.13.A.3: 'Geometric contexts involving area or two dimensions can often be modeled by quadratic functions. Geometric contexts involving volume or three dimensions can often be modeled by cubic functions.' EK 1.13.A.5: 'A polynomial function of degree n models data sets or contextual scenarios that demonstrate roughly constant nonzero nth differences.' EK 1.13.A.6: 'A polynomial function of degree n or less can be used to model a graph of n + 1 points with distinct input values.'\nWorked solutions: Example A: the table is y = x^3 + x + 1. First differences 2, 8, 20, 38; second 6, 12, 18; third 6, 6. The third differences are constant, so the degree is 3. Example B: cutting squares of side x from a 20 by 20 sheet leaves a base of side 20 - 2x and height x, so V = x(20 - 2x)^2; expanding gives 4x^3 - 80x^2 + 400x, degree 3. Example C: n + 1 = 6 means n = 5, so some polynomial of degree at most 5 passes through all six points.\nVerbal misconceptions: 'a polynomial through the points must be the true model' (fitting is not the same as explaining); 'six points need degree 6'.\nAdaptive routing: if more than 30% miss Gate Q1 or Q3, return to this slide and redo Example A and Example C."),
 dict(title="Assumptions and restrictions",rules=["\\text{assumptions: what is consistent}","\\text{restrictions: domain, range}"],
  examples=[dict(q="V(x)=x(20-2x)^{2}",steps=["\\text{base side }20-2x>0\\Rightarrow x<10","\\text{height }x>0","\\text{domain }0<x<10"]),
            dict(q="\\text{Whole tickets sold: }T(p)=120-7p",steps=["T(p)\\ge0\\Rightarrow p\\le\\dfrac{120}{7}","\\text{round }T\\text{ to a whole number}","\\text{range restriction}"]),
            dict(q="\\begin{array}{c}\\text{Fee }4\\ (w\\le1)\\\\ 4+2(w-1)\\ (w>1)\\end{array}",steps=["\\text{two rates of change}","\\text{one function cannot fit both}","\\text{piecewise-defined model}"])],fig=None,
  notes="Speaker notes (Targeted Instruction, block 3 of 3, LO 1.13.B). EK 1.13.B.1: 'A model may have underlying assumptions about what is consistent in the model.' EK 1.13.B.2: 'A model may have underlying assumptions about how quantities change together.' EK 1.13.B.3: 'A model may require domain restrictions based on mathematical clues, contextual clues, or extreme values in the data set.' EK 1.13.B.4: 'A model may require range restrictions, such as rounding values, based on mathematical clues, contextual clues, or extreme values in the data set.' EK 1.13.A.7 (piecewise-defined functions) is quoted from the fetched CED text.\nWorked solutions: Example A: the base side 20 - 2x must be positive, so x < 10, and the height x must be positive: domain 0 < x < 10. Example B: tickets cannot be negative, so p <= 120/7 (about 17.14); a count of tickets is a whole number, so the outputs are rounded: a range restriction. Example C: the fee rises at 0 per kilogram up to 1 kg and 2 per kilogram after, so the rate of change is not constant: use a piecewise-defined function.\nVerbal misconceptions: 'a model is valid for every real x'; 'a restriction is only needed when the formula has a fraction or a root'.\nAdaptive routing: if more than 30% miss Gate Q2, return to this slide and redo Example A."),
 ],
 practice=dict(practice=dict(items=["\\begin{array}{c}x:\\ 1,2,3,4\\\\ y:\\ 5,8,11,14\\end{array}"],done="Done when: you name the function type from the differences and write its equation."),
  apply=dict(items=["\\begin{array}{c}\\text{Open box from a }12\\text{ by }12\\text{ sheet, cut }x:\\\\ V(x)=x(12-2x)^{2}\\text{, domain?}\\end{array}"],done="Done when: you state the domain as an inequality and say which length forces each end."),
  investigate=dict(items=["\\begin{array}{c}\\text{Five points with distinct inputs fit a degree 4}\\\\ \\text{polynomial. Does that prove the model?}\\end{array}"],done="Done when: your explanation separates fitting the data from justifying the model type."),
  notes="Speaker notes (Practice, 12 min; tierless: students choose the starting column and may move across).\nAnswers: Practice: first differences 3, 3, 3: linear with slope 3; y = 3x + 2. Apply: base side 12 - 2x > 0 gives x < 6 and height x > 0: domain 0 < x < 6. Investigate: any n + 1 points with distinct inputs lie on some polynomial of degree n or less, so a fit through five points is always possible and says nothing about whether the context behaves that way; the model type needs a reason from the context (constant rate, area, volume).\nVerbal misconceptions: 'a perfect fit proves the model'.\nAdaptive routing: finished students move to Apply then Investigate; stuck students return to slide 5."),
 production=dict(title="ticket revenue for a science fair",context="A school science fair sells tickets. The table gives the revenue R in hundreds of dollars, for each ticket price p in dollars. The numbers are model values for practice, not real data.",
  given=["\\begin{array}{c}p:\\ 1,2,3,4,5,6\\\\ R:\\ 22,40,54,64,70,72\\end{array}","R(p)=\\ ?"],
  tasks=["Find the first and second differences and choose the function type.","Find the equation of R and predict the revenue at a price of 8 dollars.","State a domain restriction and one assumption of the model."],
  doneWhen=["Both rows of differences are shown.","The equation is checked against two table values.","The prediction at 8 dollars is given with units.","The restriction and the assumption are each stated in a full sentence."],
  hint="Hint: the second differences are constant, so the model is quadratic: start from a quadratic with three unknown coefficients.",
  notes="Speaker notes (Production, 12 min).\nSolutions: first differences 18, 14, 10, 6, 2; second differences -4, -4, -4, -4: constant, so quadratic with 2a = -4 and a = -2. Using R(1) = 22: -2 + b + c = 22; R(2) = 40: -8 + 2b + c = 40; subtracting gives b = 24 and c = 0, so R(p) = -2p^2 + 24p. Check p = 6: -72 + 144 = 72. R(8) = -128 + 192 = 64 hundred dollars, 6400 dollars. The greatest revenue is at p = 6 (72 hundred dollars). Restriction: R >= 0 needs 0 <= p <= 12, so p lies in [0, 12]. Assumption: for example, the number of buyers falls steadily as the price rises, and nothing else about the fair changes.\nVerbal misconceptions: stopping at the first differences; reading 64 as 64 dollars (it is hundreds of dollars).\nAdaptive routing: if students cannot start, send them to slide 5 Example B and the hint."),
 gate=dict(items=["\\begin{array}{c}x:\\ 0,1,2,3,4\\\\ y:\\ 1,3,11,31,69\\\\ \\text{least degree?}\\end{array}","\\begin{array}{c}A(w)=w(20-w)\\text{ for a rectangle}\\\\ \\text{of perimeter }40\\text{; domain?}\\end{array}","\\begin{array}{c}\\text{Seven points, distinct inputs.}\\\\ \\text{Degree at most?}\\end{array}"],
  notes="Speaker notes (Mastery Gate, 6 min, no calculator).\nAnswers: Q1 first differences 2, 8, 20, 38; second 6, 12, 18; third 6, 6: degree 3. Q2 both w > 0 and 20 - w > 0, so the domain is 0 < w < 20. Q3 n + 1 = 7, so n = 6: degree at most 6.\nVerbal misconceptions: Q1 'stop at the second differences and say quadratic'; Q2 'domain is all real numbers'; Q3 'degree 7'.\nAdaptive routing: Q1 missed, route to slide 6 Example A; Q2 missed, route to slide 7 Example A; Q3 missed, route to slide 6 Example C."),
 smart=dict(create=["Write a real-life scenario that a quadratic model fits and explain why in one sentence.","Write one domain restriction and one assumption for your model.","Swap with a partner: they check that the reason uses a rate of change, a shape or a geometric fact."],
  createDone="Done when: your partner confirms the model type, the restriction and the assumption.",
  exitIntro="Exit ticket: write your answer on a sticky note and place it on the door.",exit=["\\begin{array}{c}x:\\ 0,1,2,3\\\\ y:\\ 1,2,5,10\\\\ \\text{function type?}\\end{array}"],
  next="Next lesson: Topic 1.14 Function Model Construction and Application.",
  notes="Speaker notes (Smart Production, 6 min).\nExit answer: first differences 1, 3, 5; second differences 2, 2: quadratic (y = x^2 + 1).\nVerbal misconceptions: students say linear because the outputs increase; ask: are the first differences equal?"),
